请对以下 case 进行三维加权评分。

=== case_id ===
Case-03-anti-addiction-018

=== 用户原始指令 (query.txt) ===
帮我生成一个带有时间夜晚渐变和整体氛围背景的防管控卡片。背景用张暗黑系的风景照延伸出来，上面主要是写死的大字提示“今日游戏时长已用尽”，再横着排列几个锁屏、禁用、警告的静态操作项。如果接近晚上十一点就显示临近阈值风险，底部放一个明确的“去系统应用管理改限制”主动作按钮，用素材库的锁图标。

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "帮我生成一个带有时间夜晚渐变和整体氛围背景的防管控卡片。背景用张暗黑系的风景照延伸出来，上面主要是写死的大字提示“今日游戏时长已用尽”，再横着排列几个锁屏、禁用、警告的静态操作项。如果接近晚上十一点就显示临近阈值风险，底部放一个明确的“去系统应用管理改限制”主动作按钮，用素材库的锁图标。",
  "size": "2x4",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "com.huawei.hmos.settings",
        "abilityName": "com.huawei.hmos.settings.MainAbility",
        "uri": "parent_control"
      }
    }
  ],
  "dataModelSchema": {
    "status": {
      "title": {
        "type": "string",
        "description": "防沉迷卡片的主状态提示文案。",
        "sampleValue": "今日游戏时长已用尽"
      },
      "riskText": {
        "type": "string",
        "description": "接近夜间二十三点阈值时展示的风险提示。",
        "sampleValue": "临近 23:00 阈值风险"
      },
      "lockAction": {
        "type": "string",
        "description": "锁屏静态操作项标签。",
        "sampleValue": "锁屏"
      },
      "disableAction": {
        "type": "string",
        "description": "禁用静态操作项标签。",
        "sampleValue": "禁用"
      },
      "warnAction": {
        "type": "string",
        "description": "警告静态操作项标签。",
        "sampleValue": "警告"
      },
      "buttonLabel": {
        "type": "string",
        "description": "跳转系统应用管理修改限制的主动作按钮文案。",
        "sampleValue": "去系统应用管理改限制"
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/hourglass_fill.svg",
      "description": "应用时长素材图标，沙漏与齿轮组合，适合防沉迷、应用使用时长和限制管理场景。"
    }
  ]
}

